В тестах Expo инлайнит `EXPO_PUBLIC_*` на этапе трансформы — переведу чтение env на динамический ключ и перепроверю.```json
{"version":1,"taskId":"a774d560-174b-4dd3-aa4b-e675234cf2f5","commandId":"fix-mobile-env-1","operation":"run","headSha":"d0db4c9c0b6931d24eaa55511e7f39a729109667","timeoutSeconds":300,"command":"set -euo pipefail

cat > apps/mobile/src/config.ts <<'EOF'
/** Client runtime config — API base URL from Expo public env. */
const API_URL_KEY = 'EXPO_PUBLIC_API_URL';

export function getApiBaseUrl(): string {
  // Dynamic key avoids babel-preset-expo inlining process.env.EXPO_PUBLIC_* at transform time.
  return process.env[API_URL_KEY] ?? 'http://localhost:3000';
}
EOF

# quieter health test logs
cat > apps/server/src/app.ts <<'EOF'
import Fastify, { type FastifyInstance } from 'fastify';
import { API_PREFIX } from '@msngr/shared';

export async function buildApp(opts?: { logger?: boolean }): Promise<FastifyInstance> {
  const app = Fastify({ logger: opts?.logger ?? true });

  app.get('/health', async () => ({
    ok: true,
    service: 'msngr-server',
  }));

  app.get(API_PREFIX, async () => ({
    name: 'msngr',
    version: 1,
    prefix: API_PREFIX,
  }));

  return app;
}
EOF

cat > apps/server/__tests__/app.test.ts <<'EOF'
import { buildApp } from '../src/app.js';

describe('server app', () => {
  it('responds on /health', async () => {
    const app = await buildApp({ logger: false });
    const res = await app.inject({ method: 'GET', url: '/health' });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toMatchObject({ ok: true, service: 'msngr-server' });
    await app.close();
  });
});
EOF

npm run build -w @msngr/shared
npm run build -w @msngr/server
npm run typecheck
npm run lint
npm test
echo OK_VERIFY
"}
